"""One entry panel for persistent automatic intersection analysis."""
PAGE = r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Traffic Phase</title><style>*{box-sizing:border-box}body{margin:0;background:#10151d;color:#edf2fa;font:16px/1.5 system-ui}main{max-width:1300px;margin:24px auto;padding:0 16px}h1{font-size:26px}p{margin:10px 0}.muted{color:#adc0d8}section{border:1px solid #344359;border-radius:12px;padding:18px;background:#18212c;margin-bottom:16px}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}button,input,select{font:inherit;max-width:100%}button,select,input[type=datetime-local]{padding:9px;border-radius:6px;border:1px solid #4a6079}button{cursor:pointer;background:#e8f2ff;color:#10151d}button:disabled{opacity:.5;cursor:wait}input[type=file]{flex:1;min-width:200px}progress{width:100%;margin-top:12px;accent-color:#55d5af}#viewer{width:100%;height:1250px;min-height:800px;background:#0d1015;border:1px solid #344359;border-radius:12px}a{color:#a1cbff}#result-summary,#error{overflow-wrap:anywhere}#error{color:#ffacac}#session{flex:1;min-width:200px}details{margin-top:12px;font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere}#live-note{font-size:13px}</style></head><body><main>
<h1>Traffic Phase</h1><p class="muted">Фазы и сигналы перекрёстка по движению машин.</p>
<section><form id="form"><div class="row"><input id="file" type="file" accept=".json,.zip" required aria-label="Архив или JSON одного перекрёстка"><button id="analyze">Анализировать</button></div></form>
<p class="muted">Один JSON или весь ZIP одного перекрёстка. Файлы и сеансы обрабатываются автоматически; схема и число фаз пользователем не задаются.</p>
<p id="status" role="status">Выберите файл.</p><progress id="progress" hidden></progress><p id="error" role="alert"></p>
<div id="result" hidden><p id="result-summary"></p><div class="row"><label for="session">Запись</label><select id="session"></select><button id="open">Показать</button><a id="download">Скачать модель</a></div>
<p class="muted">Цвета — оценка по траекториям. Тип светофоров и допсекции пока являются гипотезой; точность восстановления всех режимов ещё проверяется.</p>
<div class="row"><button id="archiveMode">Архив</button><button id="onlineMode">Онлайн</button><label>Тестовый поток JSONL <input id="liveFile" type="file" accept=".jsonl,.ndjson"></label><label>Скорость потока <select id="liveSpeed"><option value="1">x1</option><option value="10">x10</option><option value="0">Без задержки</option></select></label><button id="liveStop">Остановить повтор</button></div>
<p id="live-note" class="muted">Онлайн использует структуру сохранённой модели. Для проверки можно воспроизвести секундные пакеты из JSONL.</p><p id="liveEndpoint" class="muted" style="overflow-wrap:anywhere"></p></div>
<details><summary>Ход обработки</summary><pre id="details"></pre></details></section>
<iframe id="viewer" title="Перекрёсток, машины и сигналы" hidden></iframe>
</main><script>
const $=id=>document.getElementById(id);let identifier=null,model=null,pollTimer=null,revision=0,viewerResize=null;
let onlineStream=null,liveTimer=null,liveToken=0,livePaused=false;
function stopLive(){liveToken++;clearTimeout(liveTimer);}
// Follow the inner content size so the user scrolls one page on desktop/mobile.
$('viewer').addEventListener('load',()=>{viewerResize?.disconnect();const content=$('viewer').contentDocument?.querySelector('main');if(!content)return;const fit=()=>{$('viewer').style.height=Math.max(800,Math.ceil(content.getBoundingClientRect().bottom+20))+'px';};viewerResize=new ResizeObserver(fit);viewerResize.observe(content);fit();});
const stages={inventory:'Проверка архива',extracting:'Чтение траекторий',discovering:'Определение фаз',catalogue:'Объединение повторяющихся режимов',finished:'Анализ завершён',queued:'Ожидание обработки',upload:'Загрузка файла'};
const fmt=new Intl.DateTimeFormat('ru-RU',{timeZone:'Asia/Yekaterinburg',dateStyle:'short',timeStyle:'medium'});
function clear(){revision++;stopLive();clearTimeout(pollTimer);$('result').hidden=true;$('viewer').hidden=true;$('viewer').removeAttribute('src');$('viewer').srcdoc='';$('error').textContent='';model=null;}
$('file').onchange=()=>{clear();$('status').textContent='Файл выбран. Нажмите «Анализировать».';};
async function poll(token){try{const response=await fetch('/api/v1/intersections/'+identifier);if(!response.ok)throw Error('Не удалось получить состояние анализа');const data=await response.json();if(token!==revision)return;
 $('status').textContent=(stages[data.stage]||data.status)+' · файлов '+(data.sources_done||0)+'/'+(data.sources_total||'?')+' · сеансов '+(data.sessions_done||0);
 if(data.sources_total){$('progress').max=data.sources_total;$('progress').value=data.sources_done;}
 $('details').textContent=(data.sources||[]).map(s=>s.source_member+' — '+s.status+(s.reason?' · '+s.reason:'')).join('\n');
 if(data.status==='FAILED')throw Error(data.reason||'Анализ не завершён');
 if(data.status==='READY'||data.status==='PARTIAL'){const r=await fetch('/api/v1/intersections/'+identifier+'/model');if(!r.ok)throw Error('Не удалось загрузить модель');model=await r.json();if(token!==revision)return;showModel();$('analyze').disabled=false;$('file').disabled=false;$('progress').hidden=true;return;}
 pollTimer=setTimeout(()=>poll(token),1000);
 }catch(error){if(token!==revision)return;$('error').textContent=error.message;$('analyze').disabled=false;$('file').disabled=false;$('progress').hidden=true;}}
function showModel(){const counts=[...new Set(model.regimes.map(r=>r.phase_count))].sort((a,b)=>a-b);$('result-summary').textContent='Наблюдаемых подходов: '+model.observed_approach_count+' ('+model.approaches.join(', ')+') · записей: '+model.sessions.length+' · групп режимов: '+model.regimes.length+' · K: '+counts.join(', ')+(model.completeness==='PARTIAL'?' · Часть данных не обработана, см. ход обработки':'');
 $('session').replaceChildren();for(const s of [...model.sessions].sort((a,b)=>a.observation_start_ms-b.observation_start_ms)){let o=new Option(fmt.format(s.observation_start_ms)+' — '+fmt.format(s.observation_end_ms)+' · K='+s.phase_count+' · '+s.source_member,s.session_id);$('session').add(o);}
 $('result').hidden=false;$('download').href='/api/v1/intersections/'+identifier+'/model';localStorage.setItem('traffic-phase-project',identifier);if(localStorage.getItem('traffic-phase-mode-'+identifier)==='online')startOnline();else openSession();}
async function openSession(){if(!model)return;stopLive();$('liveEndpoint').textContent='';localStorage.setItem('traffic-phase-mode-'+identifier,'archive');const token=revision,viewToken=liveToken,sid=$('session').value;$('viewer').hidden=true;$('status').textContent='Подготовка просмотра…';try{const response=await fetch('/api/v1/intersections/'+identifier+'/sessions/'+sid+'/viewer');const html=await response.text();if(token!==revision||viewToken!==liveToken||sid!==$('session').value)return;if(!response.ok)throw Error('Не удалось открыть запись. Попробуйте ещё раз.');$('viewer').srcdoc=html;$('viewer').hidden=false;$('status').textContent='Анализ завершён. Выберите запись или время на шкале.';}catch(error){if(token===revision)$('error').textContent=error.message;}}
$('open').onclick=openSession;$('session').onchange=openSession;
$('form').onsubmit=e=>{e.preventDefault();if(!$('file').files.length)return;clear();const token=revision;$('analyze').disabled=true;$('file').disabled=true;$('progress').hidden=false;$('progress').removeAttribute('value');$('status').textContent='Загрузка файла…';const body=new FormData();body.append('file',$('file').files[0]);const xhr=new XMLHttpRequest();xhr.open('POST','/api/v1/intersections');xhr.upload.onprogress=e=>{if(e.lengthComputable){$('progress').max=e.total;$('progress').value=e.loaded;$('status').textContent='Загрузка: '+Math.round(100*e.loaded/e.total)+'%';}};xhr.onload=()=>{if(token!==revision)return;let data;try{data=JSON.parse(xhr.responseText);}catch{}if(xhr.status!==202){$('error').textContent=String(data?.detail||'Не удалось загрузить файл');$('analyze').disabled=false;$('file').disabled=false;$('progress').hidden=true;return;}identifier=data.model_id;localStorage.setItem('traffic-phase-project',identifier);$('progress').removeAttribute('value');poll(token);};xhr.onerror=()=>{$('error').textContent='Ошибка связи при загрузке';$('analyze').disabled=false;$('file').disabled=false;$('progress').hidden=true;};xhr.send(body);};
async function onlineJSON(url,options){const response=await fetch(url,options);let data;try{data=await response.json();}catch{}if(!response.ok)throw Error(typeof data?.detail==='string'?data.detail:'Проверьте формат пакета и время детекций');return data;}
function showLive(snapshot,historical=false){if(snapshot&&(!livePaused||historical))$('viewer').contentWindow.postMessage({type:'traffic-online',snapshot,historical},location.origin);}
async function startOnline(fresh=false){if(!model)return;stopLive();livePaused=false;const token=liveToken,project=identifier;$('error').textContent='';$('status').textContent='Подготовка онлайн…';try{let stream=fresh?null:localStorage.getItem('traffic-phase-online-'+project);const base='/api/v1/intersections/'+project+'/online';if(stream){try{const state=await onlineJSON(base+'/'+stream);if(state.engine!=='causal-intersection-v4')stream=null;}catch{stream=null;}}if(!stream)stream=(await onlineJSON(base,{method:'POST'})).stream_id;if(token!==liveToken)return null;onlineStream=stream;localStorage.setItem('traffic-phase-online-'+project,stream);localStorage.setItem('traffic-phase-mode-'+project,'online');const html=await fetch(base+'/'+stream+'/viewer');if(!html.ok)throw Error('Не удалось открыть онлайн-визуализацию');const content=await html.text();if(token!==liveToken)return null;$('viewer').srcdoc=content;$('viewer').hidden=false;$('liveEndpoint').textContent='POST '+base+'/'+stream+'/packets';async function tick(){if(token!==liveToken)return;try{const data=await onlineJSON(base+'/'+stream);if(token!==liveToken)return;if(livePaused){liveTimer=setTimeout(tick,1000);return;}showLive(data.snapshot);$('status').textContent=data.snapshot?'Онлайн · пакет '+data.snapshot.sequence+' · '+fmt.format(data.snapshot.timestamp_ms):'Онлайн · ожидание пакетов';liveTimer=setTimeout(tick,1000);}catch(e){if(token===liveToken)$('error').textContent=e.message;}}tick();return {stream,token,base};}catch(e){if(token===liveToken)$('error').textContent=e.message;return null;}}
window.addEventListener('message',async event=>{if(event.source!==$('viewer').contentWindow||!onlineStream)return;if(event.data?.type==='traffic-online-resume'){startOnline();return;}if(event.data?.type!=='traffic-online-seek')return;const token=liveToken;livePaused=true;try{const value=await onlineJSON('/api/v1/intersections/'+identifier+'/online/'+onlineStream+'/at?timestamp_ms='+encodeURIComponent(event.data.timestamp_ms));if(token!==liveToken)return;if(!value.snapshot)throw Error('No accepted packet exists at this time');showLive(value.snapshot,true);$('status').textContent='Online history: '+fmt.format(value.snapshot.timestamp_ms);}catch(e){if(token===liveToken)$('error').textContent=e.message;}});
$('onlineMode').onclick=()=>startOnline();$('archiveMode').onclick=openSession;
$('liveStop').onclick=()=>{stopLive();$('status').textContent='Повтор остановлен. Принятые пакеты сохранены.';};
async function* jsonLines(file){const reader=file.stream().getReader(),decoder=new TextDecoder();let pending='';try{while(true){const chunk=await reader.read();pending+=decoder.decode(chunk.value||new Uint8Array(),{stream:!chunk.done});let index;while((index=pending.indexOf('\n'))>=0){const line=pending.slice(0,index).trim();pending=pending.slice(index+1);if(line)yield JSON.parse(line);}if(pending.length>16*1024*1024)throw Error('Слишком большой пакет JSONL');if(chunk.done)break;}if(pending.trim())yield JSON.parse(pending);}finally{reader.releaseLock();}}
$('liveFile').onchange=async()=>{const file=$('liveFile').files[0];if(!file||!model)return;const session=await startOnline(true);if(!session)return;let last=null;try{for await(const packet of jsonLines(file)){if(session.token!==liveToken)break;const speed=Number($('liveSpeed').value);if(last!==null&&speed>0)await new Promise(r=>setTimeout(r,Math.min(60000,Math.max(0,packet.timestamp_ms-last)/speed)));if(session.token!==liveToken)break;const result=await onlineJSON(session.base+'/'+session.stream+'/packets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(packet)});if(session.token!==liveToken)break;showLive(result);last=packet.timestamp_ms;$('status').textContent='Поток · пакет '+packet.sequence+' · '+fmt.format(packet.timestamp_ms);}if(session.token===liveToken)$('status').textContent='Файл потока обработан. Онлайн-подключение сохранено.';}catch(e){if(session.token===liveToken)$('error').textContent=e.message;}};
const previous=new URLSearchParams(location.search).get('project')||localStorage.getItem('traffic-phase-project');if(previous&&/^[a-f0-9]{32}$/.test(previous)){identifier=previous;$('status').textContent='Восстановление последнего анализа…';poll(revision);}
</script></body></html>'''
